import{_ as t,o as a,c as d,a3 as o}from"./chunks/framework.BTQ4eCVb.js";const m=JSON.parse('{"title":"Attendance — Developer Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Attendance — Developer Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/attendance"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Attendance — Developer Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/attendance"}]]},"headers":[],"relativePath":"developer-guide/attendance.md","filePath":"developer-guide/attendance.md","lastUpdated":1787963429000}'),n={name:"developer-guide/attendance.md"};function c(r,e,s,i,l,h){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="attendance-—-developer-guide" tabindex="-1">Attendance — Developer Guide <a class="header-anchor" href="#attendance-—-developer-guide" aria-label="Permalink to &quot;Attendance — Developer Guide&quot;">​</a></h1><p>Slug <code>attendance</code>, middleware <code>module:attendance</code>, permissions <code>attendance.*</code>. Hard-depends on <code>employees</code>. Catalog <strong>1.2.0</strong>.</p><h2 id="domain" tabindex="-1">Domain <a class="header-anchor" href="#domain" aria-label="Permalink to &quot;Domain&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Model</th><th>Table</th><th>Notes</th></tr></thead><tbody><tr><td><code>AttendanceRecord</code></td><td><code>attendance_records</code></td><td>Unique <code>(tenant_id, employee_id, date)</code>; soft deletes; work_mode + reason FKs</td></tr><tr><td><code>AttendanceReason</code></td><td><code>attendance_reasons</code></td><td>Catalog kinds <code>check_in_late</code> / <code>check_out</code>; protected <code>is_other</code></td></tr></tbody></table><p>Enums: <code>AttendanceStatusEnum</code>, <code>AttendanceWorkModeEnum</code>, <code>AttendanceReasonKindEnum</code>.</p><p>Service: <code>AttendanceRecordService</code> (CRUD + stats + today + checkIn/checkOut + optional <code>markLoginCheckIn</code>). <code>AttendanceReasonService</code> ensures Other defaults.</p><p><strong>Ownership:</strong> Staff may only act on their linked active employee. Prefer <code>POST .../check-in</code> and <code>.../check-out</code> for self-service (late classification + reasons). Admin/manager via <code>AttendanceRecordPolicy::canManageOthers</code>.</p><p>Tenant settings (<code>attendance</code> group): office hours, <code>attendance_self_check_enabled</code>, <code>attendance_auto_check_in_on_login</code> (default <strong>false</strong>), <code>attendance_require_late_reason</code>, <code>remote_office_start_time</code>, <code>remote_grace_minutes</code>, <code>work_week_days</code>. Workspace timezone drives “today” and late thresholds. Auto-login check-in is skipped when the user would be late and late reasons are required.</p><h2 id="backend-layout" tabindex="-1">Backend layout <a class="header-anchor" href="#backend-layout" aria-label="Permalink to &quot;Backend layout&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Path</th></tr></thead><tbody><tr><td>Models</td><td><code>AttendanceRecord</code>, <code>AttendanceReason</code></td></tr><tr><td>Services</td><td><code>AttendanceRecordService</code>, <code>AttendanceReasonService</code></td></tr><tr><td>Controllers</td><td><code>AttendanceRecordController</code>, <code>AttendanceReasonController</code></td></tr><tr><td>Tests</td><td><code>tests/Feature/Tenant/Attendance/</code></td></tr></tbody></table><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><p>See <a href="/api/tenant-v1-attendance">tenant-v1-attendance.md</a>.</p><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h2><ul><li><code>attendanceRecordService</code> / <code>attendanceReasonService</code></li><li>List: search + check-in/out + HH:MM timer + reasons dialog</li><li>Settings → Attendance toggles</li></ul><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --compact</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/Feature/Tenant/Attendance</span></span></code></pre></div>',16)])])}const u=t(n,[["render",c]]);export{m as __pageData,u as default};
